<?php

namespace Platform\Portal\Tests\Unit\Extensibility;

use Illuminate\Support\Facades\Event;
use Illuminate\Support\Facades\File;
use Platform\Portal\Repositories\PortalPageRepository;
use Platform\Portal\Repositories\PortalPageSectionRepository;
use Platform\Portal\Sections\SectionType;
use Platform\Portal\Sections\SectionTypeRegistry;
use Platform\Portal\Services\MenuSlotScanner;
use Platform\Portal\Services\ThemeManager;
use Tests\TestCase;

class ExtensibilityFeaturesTest extends TestCase
{
    protected function tearDown(): void
    {
        // Clean up any files generated by test
        File::deleteDirectory(app_path('Portal'));
        File::deleteDirectory(resource_path('views/portal/sections'));

        parent::tearDown();
    }

    /**
     * Test make-section artisan command scaffolds Section class and Blade view.
     */
    public function test_make_section_command_scaffolds_files(): void
    {
        $this->artisan('portal:make-section', [
            'name' => 'ShowcaseHero',
            '--force' => true,
        ])->assertSuccessful();

        $expectedClassPath = app_path('Portal/Sections/ShowcaseHeroSection.php');
        $expectedViewPath = resource_path('views/portal/sections/showcase-hero.blade.php');

        $this->assertFileExists($expectedClassPath);
        $this->assertFileExists($expectedViewPath);

        $classContent = File::get($expectedClassPath);
        $this->assertStringContainsString('class ShowcaseHeroSection extends SectionType', $classContent);
        $this->assertStringContainsString("protected string \$code = 'showcase_hero';", $classContent);
        $this->assertStringContainsString("protected ?string \$view = 'portal.sections.showcase-hero';", $classContent);

        $viewContent = File::get($expectedViewPath);
        $this->assertStringContainsString('<section', $viewContent);
        $this->assertStringContainsString('var(--bg-app)', $viewContent);
    }

    /**
     * Test dynamic menu slots from config('portal.slots') are detected by MenuSlotScanner.
     */
    public function test_dynamic_menu_slots_from_config_are_discovered(): void
    {
        config([
            'portal.slots' => [
                'custom_announcement' => [
                    'label' => 'Custom Top Announcement',
                    'location' => 'header',
                ],
                'custom_sidebar' => [
                    'label' => 'Custom Sidebar Links',
                    'location' => 'other',
                ],
            ],
        ]);

        $scanner = new MenuSlotScanner;
        $slots = $scanner->scan();

        $this->assertArrayHasKey('header', $slots);
        $this->assertArrayHasKey('custom_announcement', $slots['header']);
        $this->assertEquals('Custom Top Announcement', $slots['header']['custom_announcement']['label']);

        $this->assertArrayHasKey('other', $slots);
        $this->assertArrayHasKey('custom_sidebar', $slots['other']);
        $this->assertEquals('Custom Sidebar Links', $slots['other']['custom_sidebar']['label']);
    }

    /**
     * Test domain events are dispatched on page lifecycle and publishing.
     */
    public function test_domain_events_dispatched_on_page_lifecycle(): void
    {
        Event::fake([
            'portal.page.creating',
            'portal.page.created',
            'portal.page.updating',
            'portal.page.updated',
            'portal.page.published',
            'portal.page.deleting',
            'portal.page.deleted',
        ]);

        $pageRepo = app(PortalPageRepository::class);

        // 1. Create page
        $page = $pageRepo->create([
            'name' => 'Extensible Portal Test Page',
            'slug' => 'extensible-test-page',
            'status' => 1,
            'channel_id' => 1,
        ]);

        Event::assertDispatched('portal.page.creating');
        Event::assertDispatched('portal.page.created');

        // 2. Update page
        $pageRepo->update([
            'name' => 'Updated Portal Page',
        ], $page->id);

        Event::assertDispatched('portal.page.updating');
        Event::assertDispatched('portal.page.updated');

        // 3. Publish page sections
        $sectionRepo = app(PortalPageSectionRepository::class);
        $sectionRepo->publish($page->id);

        Event::assertDispatched('portal.page.published', function ($event, $payload) use ($page) {
            return $payload === $page->id;
        });

        // 4. Delete page
        $pageRepo->delete($page->id);

        Event::assertDispatched('portal.page.deleting');
        Event::assertDispatched('portal.page.deleted');
    }

    /**
     * Test portal:install command runs successfully.
     */
    public function test_portal_install_command(): void
    {
        $this->artisan('portal:install', [
            '--skip-seed' => true,
            '--force' => true,
        ])->assertSuccessful();

        $this->assertDirectoryExists(public_path('themes/portal/default'));
    }

    /**
     * Test portal.section.registered event is dispatched when registering a section.
     */
    public function test_section_registered_event_dispatched(): void
    {
        Event::fake(['portal.section.registered']);

        $registry = app(SectionTypeRegistry::class);

        $customSection = new class extends SectionType
        {
            protected string $code = 'event_demo_section';

            public function getFields(): array
            {
                return [];
            }

            public function getDefaultOptions(): array
            {
                return [];
            }
        };

        $registry->register($customSection);

        Event::assertDispatched('portal.section.registered');
    }

    /**
     * Test portal.theme.activating and portal.theme.activated events are dispatched.
     */
    public function test_theme_activated_events_dispatched(): void
    {
        Event::fake(['portal.theme.activating', 'portal.theme.activated']);

        $themeManager = app(ThemeManager::class);
        $themeManager->activateTheme(1, 'corporate');

        Event::assertDispatched('portal.theme.activating');
        Event::assertDispatched('portal.theme.activated');
    }
}
